import { resolveLanguageTag } from '../../i18n/deviceLanguage';
import {
  contentLanguage,
  isLanguage,
  isPseudoLanguage,
  LANGUAGES,
  type Language,
} from '../../i18n/languages';

/**
 * Country flags as system emoji (components.md §4): two regional-indicator letters make the flag. Country
 * names come from our own tables (i18n/countries/<lang>.json, generated by scripts/gen-country-names.ts), not
 * from the phone: Hermes has no Intl.DisplayNames, so the device showed two-letter codes instead of names.
 * There is a table for each of the 19 languages; a language's table is read the first time a name is asked for
 * in it (require() inside a function), so the app's start reads none of them.
 */

const REGIONAL_A = 0x1f1e6;
const ISO_ALPHA2 = /^[A-Za-z]{2}$/;

/** "IL" → 🇮🇱. Null for anything that is not a two-letter code. */
export function flagEmoji(code: string | null | undefined): string | null {
  if (!code || !ISO_ALPHA2.test(code)) return null;
  const upper = code.toUpperCase();
  return String.fromCodePoint(
    REGIONAL_A + upper.charCodeAt(0) - 'A'.charCodeAt(0),
    REGIONAL_A + upper.charCodeAt(1) - 'A'.charCodeAt(0),
  );
}

type Names = Readonly<Record<string, string>>;

const TABLES: Readonly<Record<Language, () => Names>> = {
  he: () => require('../../i18n/countries/he.json') as Names,
  en: () => require('../../i18n/countries/en.json') as Names,
  ar: () => require('../../i18n/countries/ar.json') as Names,
  es: () => require('../../i18n/countries/es.json') as Names,
  'pt-BR': () => require('../../i18n/countries/pt-BR.json') as Names,
  de: () => require('../../i18n/countries/de.json') as Names,
  fr: () => require('../../i18n/countries/fr.json') as Names,
  ja: () => require('../../i18n/countries/ja.json') as Names,
  ru: () => require('../../i18n/countries/ru.json') as Names,
  ko: () => require('../../i18n/countries/ko.json') as Names,
  it: () => require('../../i18n/countries/it.json') as Names,
  tr: () => require('../../i18n/countries/tr.json') as Names,
  'zh-Hans': () => require('../../i18n/countries/zh-Hans.json') as Names,
  id: () => require('../../i18n/countries/id.json') as Names,
  pl: () => require('../../i18n/countries/pl.json') as Names,
  'zh-Hant': () => require('../../i18n/countries/zh-Hant.json') as Names,
  vi: () => require('../../i18n/countries/vi.json') as Names,
  th: () => require('../../i18n/countries/th.json') as Names,
  nl: () => require('../../i18n/countries/nl.json') as Names,
};

/**
 * The table an app language reads, by its whole code after the device mapping (D105: he-IL and the old iw as
 * he, zh-TW as zh-Hant, so the two Chinese tables stay apart). The pseudo languages (en-XA, ar-XB) and anything
 * else read English (D101).
 */
export function countryNamesLanguage(language: string): Language {
  if (isPseudoLanguage(language)) return 'en';
  const lang = contentLanguage(resolveLanguageTag(language, LANGUAGES) ?? language, LANGUAGES);
  return isLanguage(lang) ? lang : 'en';
}

/** Every country the server accepts (COUNTRY_CODES), by code, in one language of the app. */
export function countryNames(language: Language): Names {
  return TABLES[language]();
}

/** The country's full name in the app language ("IL" → "ישראל"); the code itself for a code we don't know. */
export function countryName(code: string, language: string): string {
  const upper = code.toUpperCase();
  return countryNames(countryNamesLanguage(language))[upper] ?? upper;
}
